-- CLO 2.0 rule library.
--
-- Rules for a CLO fund (FUND_STRUCTURE = 'CLO'), built on the compliance engine
-- and the composite_ratio path added in 20261106110000_clo_compliance_engine:
--
--   COVERAGE            overcollateralization and interest coverage by note class
--   COLLATERAL_QUALITY  WARF, WAS, WAL, WARR
--   CONCENTRATION       CCC, covenant-lite, second lien, fixed rate, discount, non-USD,
--                       participations, deferring, revolver and delayed draw,
--                       single obligor, industry
--   ELIGIBILITY         prohibited types, convertibles, stated maturity, rating floors
--
-- Limits come from the CLO_TRANSACTION and CLO_NOTE_CLASS attributes of the fund
-- (limit_term), so each deal carries its own indenture numbers. A fund row in
-- compliance.rule_thresholds overrides them. Where a rule has no number in the
-- indenture data and no default here it reports NO_DATA, not a pass.
--
-- Defaults written here are conventional CLO 2.0 values: 2.0 percent single
-- obligor, 7.5 percent CCC, 60 percent covenant-lite, and industry caps of 12
-- percent for the largest and 10 percent for the rest. Confirm each against the
-- deal indenture before relying on it.
--
-- Every rule is pre_trade: evaluate_pre_trade checks it for maintain-or-improve.
-- Not covered yet: Moody's diversity score, jurisdiction against the permitted
-- list, and the S&P CDO Monitor.

INSERT INTO compliance.rules (
    rule_code, rule_name, rule_category, anchor_domain_code, applies_to_all, is_active, description, metadata
) VALUES
    ('CLO_OC_AB', 'Class A/B Overcollateralization Test', 'COVERAGE', 'FUND', TRUE, TRUE, 'Adjusted collateral principal amount over the par of every note class ranked 2 or better. Performing par, plus defaulted obligations at carry value, less the excess-CCC and discount haircuts, plus principal and ramp-up cash. The trigger is read from the class OC trigger.', '{"family":"CLO"}'::jsonb),
    ('CLO_OC_C', 'Class C Overcollateralization Test', 'COVERAGE', 'FUND', TRUE, TRUE, 'Adjusted collateral principal amount over the par of every note class ranked 3 or better. Performing par, plus defaulted obligations at carry value, less the excess-CCC and discount haircuts, plus principal and ramp-up cash. The trigger is read from the class OC trigger.', '{"family":"CLO"}'::jsonb),
    ('CLO_OC_D', 'Class D Overcollateralization Test', 'COVERAGE', 'FUND', TRUE, TRUE, 'Adjusted collateral principal amount over the par of every note class ranked 4 or better. Performing par, plus defaulted obligations at carry value, less the excess-CCC and discount haircuts, plus principal and ramp-up cash. The trigger is read from the class OC trigger.', '{"family":"CLO"}'::jsonb),
    ('CLO_OC_E', 'Class E Overcollateralization Test', 'COVERAGE', 'FUND', TRUE, TRUE, 'Adjusted collateral principal amount over the par of every note class ranked 5 or better. Performing par, plus defaulted obligations at carry value, less the excess-CCC and discount haircuts, plus principal and ramp-up cash. The trigger is read from the class OC trigger.', '{"family":"CLO"}'::jsonb),
    ('CLO_IC_AB', 'Class A/B Interest Coverage Test', 'COVERAGE', 'FUND', TRUE, TRUE, 'Interest collections less senior expenses, over the interest due on every note class ranked 2 or better. The trigger is read from the class IC trigger.', '{"family":"CLO"}'::jsonb),
    ('CLO_IC_C', 'Class C Interest Coverage Test', 'COVERAGE', 'FUND', TRUE, TRUE, 'Interest collections less senior expenses, over the interest due on every note class ranked 3 or better. The trigger is read from the class IC trigger.', '{"family":"CLO"}'::jsonb),
    ('CLO_IC_D', 'Class D Interest Coverage Test', 'COVERAGE', 'FUND', TRUE, TRUE, 'Interest collections less senior expenses, over the interest due on every note class ranked 4 or better. The trigger is read from the class IC trigger.', '{"family":"CLO"}'::jsonb),
    ('CLO_WARF', 'Weighted Average Rating Factor', 'COLLATERAL_QUALITY', 'FUND', TRUE, TRUE, 'Par-weighted Moody''s rating factor of performing obligations. Limit is the selected Moody''s matrix cell.', '{"family":"CLO"}'::jsonb),
    ('CLO_WAS', 'Weighted Average Spread', 'COLLATERAL_QUALITY', 'FUND', TRUE, TRUE, 'Par-weighted spread in bps of performing floating-rate obligations. The spread is the contractual spread. The effect of a benchmark floor is not included.', '{"family":"CLO"}'::jsonb),
    ('CLO_WAL', 'Weighted Average Life', 'COLLATERAL_QUALITY', 'FUND', TRUE, TRUE, 'Par-weighted years from the as-of date to maturity of performing obligations. Limit is the step-down schedule value now in force.', '{"family":"CLO"}'::jsonb),
    ('CLO_WARR', 'Weighted Average Recovery Rate', 'COLLATERAL_QUALITY', 'FUND', TRUE, TRUE, 'Par-weighted Moody''s recovery rate of performing obligations, in percent.', '{"family":"CLO"}'::jsonb),
    ('CLO_CONC_CCC', 'CCC Bucket', 'CONCENTRATION', 'FUND', TRUE, TRUE, 'Performing obligations rated CCC+/Caa1 or lower over collateral par. The excess above the cap is reported as excess_amount and haircut in the OC tests.', '{"family":"CLO"}'::jsonb),
    ('CLO_CONC_COV_LITE', 'Covenant-Lite Loans', 'CONCENTRATION', 'FUND', TRUE, TRUE, 'Covenant-lite loans over collateral par.', '{"family":"CLO"}'::jsonb),
    ('CLO_CONC_SECOND_LIEN', 'Second Lien Loans', 'CONCENTRATION', 'FUND', TRUE, TRUE, 'Second lien loans over collateral par.', '{"family":"CLO"}'::jsonb),
    ('CLO_CONC_FIXED_RATE', 'Fixed Rate Obligations', 'CONCENTRATION', 'FUND', TRUE, TRUE, 'Fixed rate obligations over collateral par.', '{"family":"CLO"}'::jsonb),
    ('CLO_CONC_DISCOUNT', 'Discount Obligations', 'CONCENTRATION', 'FUND', TRUE, TRUE, 'Discount obligations over collateral par.', '{"family":"CLO"}'::jsonb),
    ('CLO_CONC_NON_USD', 'Non-USD Obligations', 'CONCENTRATION', 'FUND', TRUE, TRUE, 'Obligations not denominated in USD over collateral par.', '{"family":"CLO"}'::jsonb),
    ('CLO_CONC_PARTICIPATION', 'Participations', 'CONCENTRATION', 'FUND', TRUE, TRUE, 'Participation interests over collateral par.', '{"family":"CLO"}'::jsonb),
    ('CLO_CONC_DEFERRING', 'Deferring Obligations', 'CONCENTRATION', 'FUND', TRUE, TRUE, 'Obligations deferring or capitalizing interest over collateral par.', '{"family":"CLO"}'::jsonb),
    ('CLO_CONC_REVOLVER_DDTL', 'Revolving and Delayed Draw Obligations', 'CONCENTRATION', 'FUND', TRUE, TRUE, 'Revolvers plus delayed draw term loans over collateral par. The funded and unfunded commitment both count.', '{"family":"CLO"}'::jsonb),
    ('CLO_CONC_SINGLE_OBLIGOR', 'Single Obligor Cap', 'CONCENTRATION', 'FUND', TRUE, TRUE, 'Par of each obligor group over collateral par. Obligors are grouped on OBLIGOR_GROUP_ID, so every issuer needs one (use the ultimate parent when there is no wider group).', '{"family":"CLO"}'::jsonb),
    ('CLO_CONC_INDUSTRY', 'Industry Concentration', 'CONCENTRATION', 'FUND', TRUE, TRUE, 'Par of each Moody''s industry over collateral par. The largest industry may reach 12 percent and every other industry 10 percent. The rank limits are rule_thresholds rows and can be set per fund.', '{"family":"CLO"}'::jsonb),
    ('CLO_ELIG_LOAN_TYPE', 'Prohibited Obligation Type', 'ELIGIBILITY', 'FUND', TRUE, TRUE, 'Count of holdings that are bridge loans, structured finance, synthetic securities or zero coupon obligations.', '{"family":"CLO"}'::jsonb),
    ('CLO_ELIG_CONVERTIBLE', 'Convertible Obligation', 'ELIGIBILITY', 'FUND', TRUE, TRUE, 'Count of holdings that can convert into equity or another currency.', '{"family":"CLO"}'::jsonb),
    ('CLO_ELIG_STATED_MATURITY', 'Maturity Beyond Stated Maturity', 'ELIGIBILITY', 'FUND', TRUE, TRUE, 'Count of holdings that mature after the stated maturity of the notes.', '{"family":"CLO"}'::jsonb),
    ('CLO_ELIG_RATING_SP', 'S&P Rating Floor', 'ELIGIBILITY', 'FUND', TRUE, TRUE, 'Count of holdings rated below CCC- by S&P.', '{"family":"CLO"}'::jsonb),
    ('CLO_ELIG_RATING_MOODYS', 'Moody''s Rating Floor', 'ELIGIBILITY', 'FUND', TRUE, TRUE, 'Count of holdings rated below Caa3 by Moody''s.', '{"family":"CLO"}'::jsonb)
ON CONFLICT (rule_code) DO UPDATE
SET rule_name = EXCLUDED.rule_name,
    rule_category = EXCLUDED.rule_category,
    description = EXCLUDED.description,
    metadata = EXCLUDED.metadata,
    anchor_domain_code = EXCLUDED.anchor_domain_code,
    applies_to_all = TRUE,
    is_active = TRUE;

INSERT INTO compliance.rule_versions (
    rule_id, version_number, valid_from, rule_name, description, base_domain_code,
    base_rollup_path, group_by_path, group_by_attribute_code,
    numerator_attribute_code, numerator_aggregation,
    denominator_attribute_code, denominator_aggregation, denominator_scope, denominator_source,
    limit_direction, soft_limit_value, hard_limit_value,
    result_unit, metadata
)
SELECT r.id, 1, DATE '2020-01-01', r.rule_name, v.descr, v.base_domain,
       v.base_path::jsonb, v.group_path::jsonb, v.group_attr,
       v.num_attr, v.num_agg,
       v.den_attr, v.den_agg, v.den_scope, v.den_source,
       v.direction, v.soft, v.hard,
       v.unit, v.meta::jsonb
FROM compliance.rules r
JOIN (VALUES
    ('CLO_OC_AB', 'Adjusted collateral principal amount over the par of every note class ranked 2 or better. Performing par, plus defaulted obligations at carry value, less the excess-CCC and discount haircuts, plus principal and ramp-up cash. The trigger is read from the class OC trigger.', 'POSITION', '[]', '[]', NULL::varchar, 'FUNDED_PAR_AMOUNT', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MIN', NULL::numeric, NULL::numeric, 'PERCENTAGE', '{"logic":"composite_ratio","numerator_terms":[{"label":"Performing par","kind":"SUM","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_DEFAULTED","op":"not_equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}]},{"label":"Defaulted obligations at carry value","kind":"SUM","attribute":"CLO_DEFAULT_CARRY_VALUE","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_DEFAULTED","op":"equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}]},{"label":"Excess CCC haircut","kind":"EXCESS_OVER_PCT","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_DEFAULTED","op":"not_equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]},{"attribute":"CLO_IS_CCC","op":"equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}],"sign":-1,"total_where":[{"attribute":"IS_DEFAULTED","op":"not_equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}],"pct_term":{"kind":"MAX","attribute":"CLO_MAX_CCC_PCT","path":[{"relationship_code":"FUND_CLO_TRANSACTION","direction":"DOWN","recursive":false}]},"price_attribute":"FAIR_MARKET_PRICE"},{"label":"Discount obligation haircut","kind":"SUM","attribute":"CLO_DISCOUNT_HAIRCUT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_DEFAULTED","op":"not_equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]},{"attribute":"CLO_IS_DISCOUNT_OBLIGATION","op":"equals","value":"true"}],"sign":-1},{"label":"Principal and ramp-up cash","kind":"SUM","attribute":"CLO_ACCT_BALANCE","path":[{"relationship_code":"FUND_CLO_ACCOUNT","direction":"DOWN","recursive":false}],"where":[{"attribute":"CLO_ACCT_TYPE","op":"in","value":["PRINCIPAL","RAMP_UP"]}]}],"scenario_mode":"strict","pre_trade":true,"denominator_terms":[{"label":"Par of notes ranked 2 or better","kind":"SUM","attribute":"CLO_NOTE_PAR_OUTSTANDING","path":[{"relationship_code":"FUND_CLO_NOTE_CLASS","direction":"DOWN","recursive":false}],"where":[{"attribute":"CLO_NOTE_SENIORITY_RANK","op":"lte","value":"2"}],"required":true}],"limit_term":{"kind":"MAX","attribute":"CLO_NOTE_OC_TRIGGER","path":[{"relationship_code":"FUND_CLO_NOTE_CLASS","direction":"DOWN","recursive":false}],"where":[{"attribute":"CLO_NOTE_SENIORITY_RANK","op":"equals","value":"2"}]}}'),
    ('CLO_OC_C', 'Adjusted collateral principal amount over the par of every note class ranked 3 or better. Performing par, plus defaulted obligations at carry value, less the excess-CCC and discount haircuts, plus principal and ramp-up cash. The trigger is read from the class OC trigger.', 'POSITION', '[]', '[]', NULL::varchar, 'FUNDED_PAR_AMOUNT', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MIN', NULL::numeric, NULL::numeric, 'PERCENTAGE', '{"logic":"composite_ratio","numerator_terms":[{"label":"Performing par","kind":"SUM","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_DEFAULTED","op":"not_equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}]},{"label":"Defaulted obligations at carry value","kind":"SUM","attribute":"CLO_DEFAULT_CARRY_VALUE","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_DEFAULTED","op":"equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}]},{"label":"Excess CCC haircut","kind":"EXCESS_OVER_PCT","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_DEFAULTED","op":"not_equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]},{"attribute":"CLO_IS_CCC","op":"equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}],"sign":-1,"total_where":[{"attribute":"IS_DEFAULTED","op":"not_equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}],"pct_term":{"kind":"MAX","attribute":"CLO_MAX_CCC_PCT","path":[{"relationship_code":"FUND_CLO_TRANSACTION","direction":"DOWN","recursive":false}]},"price_attribute":"FAIR_MARKET_PRICE"},{"label":"Discount obligation haircut","kind":"SUM","attribute":"CLO_DISCOUNT_HAIRCUT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_DEFAULTED","op":"not_equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]},{"attribute":"CLO_IS_DISCOUNT_OBLIGATION","op":"equals","value":"true"}],"sign":-1},{"label":"Principal and ramp-up cash","kind":"SUM","attribute":"CLO_ACCT_BALANCE","path":[{"relationship_code":"FUND_CLO_ACCOUNT","direction":"DOWN","recursive":false}],"where":[{"attribute":"CLO_ACCT_TYPE","op":"in","value":["PRINCIPAL","RAMP_UP"]}]}],"scenario_mode":"strict","pre_trade":true,"denominator_terms":[{"label":"Par of notes ranked 3 or better","kind":"SUM","attribute":"CLO_NOTE_PAR_OUTSTANDING","path":[{"relationship_code":"FUND_CLO_NOTE_CLASS","direction":"DOWN","recursive":false}],"where":[{"attribute":"CLO_NOTE_SENIORITY_RANK","op":"lte","value":"3"}],"required":true}],"limit_term":{"kind":"MAX","attribute":"CLO_NOTE_OC_TRIGGER","path":[{"relationship_code":"FUND_CLO_NOTE_CLASS","direction":"DOWN","recursive":false}],"where":[{"attribute":"CLO_NOTE_SENIORITY_RANK","op":"equals","value":"3"}]}}'),
    ('CLO_OC_D', 'Adjusted collateral principal amount over the par of every note class ranked 4 or better. Performing par, plus defaulted obligations at carry value, less the excess-CCC and discount haircuts, plus principal and ramp-up cash. The trigger is read from the class OC trigger.', 'POSITION', '[]', '[]', NULL::varchar, 'FUNDED_PAR_AMOUNT', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MIN', NULL::numeric, NULL::numeric, 'PERCENTAGE', '{"logic":"composite_ratio","numerator_terms":[{"label":"Performing par","kind":"SUM","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_DEFAULTED","op":"not_equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}]},{"label":"Defaulted obligations at carry value","kind":"SUM","attribute":"CLO_DEFAULT_CARRY_VALUE","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_DEFAULTED","op":"equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}]},{"label":"Excess CCC haircut","kind":"EXCESS_OVER_PCT","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_DEFAULTED","op":"not_equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]},{"attribute":"CLO_IS_CCC","op":"equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}],"sign":-1,"total_where":[{"attribute":"IS_DEFAULTED","op":"not_equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}],"pct_term":{"kind":"MAX","attribute":"CLO_MAX_CCC_PCT","path":[{"relationship_code":"FUND_CLO_TRANSACTION","direction":"DOWN","recursive":false}]},"price_attribute":"FAIR_MARKET_PRICE"},{"la