    ('CLO_OC_E', 'Adjusted collateral principal amount over the par of every note class ranked 5 or better. Performing par, plus defaulted obligations at carry value, less the excess-CCC and discount haircuts, plus principal and ramp-up cash. The trigger is read from the class OC trigger.', 'POSITION', '[]', '[]', NULL::varchar, 'FUNDED_PAR_AMOUNT', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MIN', NULL::numeric, NULL::numeric, 'PERCENTAGE', '{"logic":"composite_ratio","numerator_terms":[{"label":"Performing par","kind":"SUM","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_DEFAULTED","op":"not_equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}]},{"label":"Defaulted obligations at carry value","kind":"SUM","attribute":"CLO_DEFAULT_CARRY_VALUE","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_DEFAULTED","op":"equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}]},{"label":"Excess CCC haircut","kind":"EXCESS_OVER_PCT","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_DEFAULTED","op":"not_equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]},{"attribute":"CLO_IS_CCC","op":"equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}],"sign":-1,"total_where":[{"attribute":"IS_DEFAULTED","op":"not_equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}],"pct_term":{"kind":"MAX","attribute":"CLO_MAX_CCC_PCT","path":[{"relationship_code":"FUND_CLO_TRANSACTION","direction":"DOWN","recursive":false}]},"price_attribute":"FAIR_MARKET_PRICE"},{"la