    ('CLO_IC_AB', 'Interest collections less senior expenses, over the interest due on every note class ranked 2 or better. The trigger is read from the class IC trigger.', 'POSITION', '[]', '[]', NULL::varchar, 'FUNDED_PAR_AMOUNT', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MIN', NULL::numeric, NULL::numeric, 'PERCENTAGE', '{"logic":"composite_ratio","numerator_terms":[{"label":"Expected interest collections","kind":"SUM","attribute":"CLO_EXPECTED_INTEREST","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}]},{"label":"Senior expenses","kind":"SUM","attribute":"CLO_SENIOR_EXPENSES","path":[{"relationship_code":"FUND_CLO_TRANSACTION","direction":"DOWN","recursive":false}],"sign":-1}],"scenario_mode":"strict","pre_trade":true,"denominator_terms":[{"label":"Interest due on notes ranked 2 or better","kind":"SUM","attribute":"CLO_NOTE_INTEREST_DUE","path":[{"relationship_code":"FUND_CLO_NOTE_CLASS","direction":"DOWN","recursive":false}],"where":[{"attribute":"CLO_NOTE_SENIORITY_RANK","op":"lte","value":"2"}],"required":true}],"limit_term":{"kind":"MAX","attribute":"CLO_NOTE_IC_TRIGGER","path":[{"relationship_code":"FUND_CLO_NOTE_CLASS","direction":"DOWN","recursive":false}],"where":[{"attribute":"CLO_NOTE_SENIORITY_RANK","op":"equals","value":"2"}]}}'),
    ('CLO_IC_C', 'Interest collections less senior expenses, over the interest due on every note class ranked 3 or better. The trigger is read from the class IC trigger.', 'POSITION', '[]', '[]', NULL::varchar, 'FUNDED_PAR_AMOUNT', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MIN', NULL::numeric, NULL::numeric, 'PERCENTAGE', '{"logic":"composite_ratio","numerator_terms":[{"label":"Expected interest collections","kind":"SUM","attribute":"CLO_EXPECTED_INTEREST","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}]},{"label":"Senior expenses","kind":"SUM","attribute":"CLO_SENIOR_EXPENSES","path":[{"relationship_code":"FUND_CLO_TRANSACTION","direction":"DOWN","recursive":false}],"sign":-1}],"scenario_mode":"strict","pre_trade":true,"denominator_terms":[{"label":"Interest due on notes ranked 3 or better","kind":"SUM","attribute":"CLO_NOTE_INTEREST_DUE","path":[{"relationship_code":"FUND_CLO_NOTE_CLASS","direction":"DOWN","recursive":false}],"where":[{"attribute":"CLO_NOTE_SENIORITY_RANK","op":"lte","value":"3"}],"required":true}],"limit_term":{"kind":"MAX","attribute":"CLO_NOTE_IC_TRIGGER","path":[{"relationship_code":"FUND_CLO_NOTE_CLASS","direction":"DOWN","recursive":false}],"where":[{"attribute":"CLO_NOTE_SENIORITY_RANK","op":"equals","value":"3"}]}}'),
    ('CLO_IC_D', 'Interest collections less senior expenses, over the interest due on every note class ranked 4 or better. The trigger is read from the class IC trigger.', 'POSITION', '[]', '[]', NULL::varchar, 'FUNDED_PAR_AMOUNT', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MIN', NULL::numeric, NULL::numeric, 'PERCENTAGE', '{"logic":"composite_ratio","numerator_terms":[{"label":"Expected interest collections","kind":"SUM","attribute":"CLO_EXPECTED_INTEREST","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}]},{"label":"Senior expenses","kind":"SUM","attribute":"CLO_SENIOR_EXPENSES","path":[{"relationship_code":"FUND_CLO_TRANSACTION","direction":"DOWN","recursive":false}],"sign":-1}],"scenario_mode":"strict","pre_trade":true,"denominator_terms":[{"label":"Interest due on notes ranked 4 or better","kind":"SUM","attribute":"CLO_NOTE_INTEREST_DUE","path":[{"relationship_code":"FUND_CLO_NOTE_CLASS","direction":"DOWN","recursive":false}],"where":[{"attribute":"CLO_NOTE_SENIORITY_RANK","op":"lte","value":"4"}],"required":true}],"limit_term":{"kind":"MAX","attribute":"CLO_NOTE_IC_TRIGGER","path":[{"relationship_code":"FUND_CLO_NOTE_CLASS","direction":"DOWN","recursive":false}],"where":[{"attribute":"CLO_NOTE_SENIORITY_RANK","op":"equals","value":"4"}]}}'),
    ('CLO_WARF', 'Par-weighted Moody''s rating factor of performing obligations. Limit is the selected Moody''s matrix cell.', 'POSITION', '[]', '[]', NULL::varchar, 'CLO_MOODYS_RATING_FACTOR', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MAX', NULL::numeric, NULL::numeric, 'RATIO', '{"logic":"composite_ratio","numerator_terms":[{"label":"Weighted Average Rating Factor","kind":"WAVG","attribute":"CLO_MOODYS_RATING_FACTOR","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_DEFAULTED","op":"not_equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}],"weight_attribute":"FUNDED_PAR_AMOUNT","value_path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}],"required":true}],"scenario_mode":"strict","pre_trade":true,"limit_term":{"kind":"MAX","attribute":"CLO_MAX_WARF","path":[{"relationship_code":"FUND_CLO_TRANSACTION","direction":"DOWN","recursive":false}]}}'),
    ('CLO_WAS', 'Par-weighted spread in bps of performing floating-rate obligations. The spread is the contractual spread. The effect of a benchmark floor is not included.', 'POSITION', '[]', '[]', NULL::varchar, 'SPREAD_BPS', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MIN', NULL::numeric, NULL::numeric, 'RATIO', '{"logic":"composite_ratio","numerator_terms":[{"label":"Weighted Average Spread","kind":"WAVG","attribute":"SPREAD_BPS","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_DEFAULTED","op":"not_equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]},{"attribute":"IS_FIXED_RATE","op":"not_equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}],"weight_attribute":"FUNDED_PAR_AMOUNT","value_path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}],"required":true}],"scenario_mode":"strict","pre_trade":true,"limit_term":{"kind":"MAX","attribute":"CLO_MIN_WAS_BPS","path":[{"relationship_code":"FUND_CLO_TRANSACTION","direction":"DOWN","recursive":false}]}}'),
    ('CLO_WAL', 'Par-weighted years from the as-of date to maturity of performing obligations. Limit is the step-down schedule value now in force.', 'POSITION', '[]', '[]', NULL::varchar, 'MATURITY_DATE', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MAX', NULL::numeric, NULL::numeric, 'RATIO', '{"logic":"composite_ratio","numerator_terms":[{"label":"Weighted Average Life","kind":"WAVG","attribute":"MATURITY_DATE","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_DEFAULTED","op":"not_equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}],"weight_attribute":"FUNDED_PAR_AMOUNT","value_path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}],"required":true,"transform":"YEARS_TO_DATE"}],"scenario_mode":"strict","pre_trade":true,"limit_term":{"kind":"MAX","attribute":"CLO_MAX_WAL_YEARS","path":[{"relationship_code":"FUND_CLO_TRANSACTION","direction":"DOWN","recursive":false}]}}'),
    ('CLO_WARR', 'Par-weighted Moody''s recovery rate of performing obligations, in percent.', 'POSITION', '[]', '[]', NULL::varchar, 'CLO_MOODYS_RECOVERY_RATE', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MIN', NULL::numeric, NULL::numeric, 'PERCENTAGE', '{"logic":"composite_ratio","numerator_terms":[{"label":"Weighted Average Recovery Rate","kind":"WAVG","attribute":"CLO_MOODYS_RECOVERY_RATE","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_DEFAULTED","op":"not_equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}],"weight_attribute":"FUNDED_PAR_AMOUNT","value_path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}],"required":true}],"scenario_mode":"strict","pre_trade":true,"limit_term":{"kind":"MAX","attribute":"CLO_MIN_WARR","path":[{"relationship_code":"FUND_CLO_TRANSACTION","direction":"DOWN","recursive":false}]}}'),
    ('CLO_CONC_CCC', 'Performing obligations rated CCC+/Caa1 or lower over collateral par. The excess above the cap is reported as excess_amount and haircut in the OC tests.', 'POSITION', '[]', '[]', NULL::varchar, 'FUNDED_PAR_AMOUNT', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MAX', NULL::numeric, 7.5::numeric, 'PERCENTAGE', '{"logic":"composite_ratio","numerator_terms":[{"label":"CCC Bucket par","kind":"SUM","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_DEFAULTED","op":"not_equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]},{"attribute":"CLO_IS_CCC","op":"equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}]}],"scenario_mode":"strict","pre_trade":true,"denominator_terms":[{"label":"Collateral par","kind":"SUM","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}]}],"limit_term":{"kind":"MAX","attribute":"CLO_MAX_CCC_PCT","path":[{"relationship_code":"FUND_CLO_TRANSACTION","direction":"DOWN","recursive":false}]}}'),
    ('CLO_CONC_COV_LITE', 'Covenant-lite loans over collateral par.', 'POSITION', '[]', '[]', NULL::varchar, 'FUNDED_PAR_AMOUNT', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MAX', NULL::numeric, 60.0::numeric, 'PERCENTAGE', '{"logic":"composite_ratio","numerator_terms":[{"label":"Covenant-Lite Loans par","kind":"SUM","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_COV_LITE","op":"equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}]}],"scenario_mode":"strict","pre_trade":true,"denominator_terms":[{"label":"Collateral par","kind":"SUM","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}]}],"limit_term":{"kind":"MAX","attribute":"CLO_MAX_COV_LITE_PCT","path":[{"relationship_code":"FUND_CLO_TRANSACTION","direction":"DOWN","recursive":false}]}}'),
    ('CLO_CONC_SECOND_LIEN', 'Second lien loans over collateral par.', 'POSITION', '[]', '[]', NULL::varchar, 'FUNDED_PAR_AMOUNT', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MAX', NULL::numeric, NULL::numeric, 'PERCENTAGE', '{"logic":"composite_ratio","numerator_terms":[{"label":"Second Lien Loans par","kind":"SUM","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"LIEN_PRIORITY","op":"equals","value":"SECOND_LIEN","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}]}],"scenario_mode":"strict","pre_trade":true,"denominator_terms":[{"label":"Collateral par","kind":"SUM","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}]}],"limit_term":{"kind":"MAX","attribute":"CLO_MAX_SECOND_LIEN_PCT","path":[{"relationship_code":"FUND_CLO_TRANSACTION","direction":"DOWN","recursive":false}]}}'),
    ('CLO_CONC_FIXED_RATE', 'Fixed rate obligations over collateral par.', 'POSITION', '[]', '[]', NULL::varchar, 'FUNDED_PAR_AMOUNT', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MAX', NULL::numeric, NULL::numeric, 'PERCENTAGE', '{"logic":"composite_ratio","numerator_terms":[{"label":"Fixed Rate Obligations par","kind":"SUM","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_FIXED_RATE","op":"equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}]}],"scenario_mode":"strict","pre_trade":true,"denominator_terms":[{"label":"Collateral par","kind":"SUM","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}]}],"limit_term":{"kind":"MAX","attribute":"CLO_MAX_FIXED_RATE_PCT","path":[{"relationship_code":"FUND_CLO_TRANSACTION","direction":"DOWN","recursive":false}]}}'),
    ('CLO_CONC_DISCOUNT', 'Discount obligations over collateral par.', 'POSITION', '[]', '[]', NULL::varchar, 'FUNDED_PAR_AMOUNT', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MAX', NULL::numeric, NULL::numeric, 'PERCENTAGE', '{"logic":"composite_ratio","numerator_terms":[{"label":"Discount Obligations par","kind":"SUM","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"CLO_IS_DISCOUNT_OBLIGATION","op":"equals","value":"true"}]}],"scenario_mode":"strict","pre_trade":true,"denominator_terms":[{"label":"Collateral par","kind":"SUM","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}]}],"limit_term":{"kind":"MAX","attribute":"CLO_MAX_DISCOUNT_PCT","path":[{"relationship_code":"FUND_CLO_TRANSACTION","direction":"DOWN","recursive":false}]}}'),
    ('CLO_CONC_NON_USD', 'Obligations not denominated in USD over collateral par.', 'POSITION', '[]', '[]', NULL::varchar, 'FUNDED_PAR_AMOUNT', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MAX', NULL::numeric, NULL::numeric, 'PERCENTAGE', '{"logic":"composite_ratio","numerator_terms":[{"label":"Non-USD Obligations par","kind":"SUM","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"DENOMINATION_CURRENCY","op":"not_equals","value":"USD","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}]}],"scenario_mode":"strict","pre_trade":true,"denominator_terms":[{"label":"Collateral par","kind":"SUM","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}]}],"limit_term":{"kind":"MAX","attribute":"CLO_MAX_NON_USD_PCT","path":[{"relationship_code":"FUND_CLO_TRANSACTION","direction":"DOWN","recursive":false}]}}'),
    ('CLO_CONC_PARTICIPATION', 'Participation interests over collateral par.', 'POSITION', '[]', '[]', NULL::varchar, 'FUNDED_PAR_AMOUNT', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MAX', NULL::numeric, NULL::numeric, 'PERCENTAGE', '{"logic":"composite_ratio","numerator_terms":[{"label":"Participations par","kind":"SUM","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_PARTICIPATION","op":"equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}]}],"scenario_mode":"strict","pre_trade":true,"denominator_terms":[{"label":"Collateral par","kind":"SUM","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}]}],"limit_term":{"kind":"MAX","attribute":"CLO_MAX_PARTICIPATION_PCT","path":[{"relationship_code":"FUND_CLO_TRANSACTION","direction":"DOWN","recursive":false}]}}'),
    ('CLO_CONC_DEFERRING', 'Obligations deferring or capitalizing interest over collateral par.', 'POSITION', '[]', '[]', NULL::varchar, 'FUNDED_PAR_AMOUNT', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MAX', NULL::numeric, NULL::numeric, 'PERCENTAGE', '{"logic":"composite_ratio","numerator_terms":[{"label":"Deferring Obligations par","kind":"SUM","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_DEFERRING_INTEREST","op":"equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}]}],"scenario_mode":"strict","pre_trade":true,"denominator_terms":[{"label":"Collateral par","kind":"SUM","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}]}],"limit_term":{"kind":"MAX","attribute":"CLO_MAX_DEFERRING_PCT","path":[{"relationship_code":"FUND_CLO_TRANSACTION","direction":"DOWN","recursive":false}]}}'),
    ('CLO_CONC_REVOLVER_DDTL', 'Revolvers plus delayed draw term loans over collateral par. The funded and unfunded commitment both count.', 'POSITION', '[]', '[]', NULL::varchar, 'FUNDED_PAR_AMOUNT', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MAX', NULL::numeric, NULL::numeric, 'PERCENTAGE', '{"logic":"composite_ratio","numerator_terms":[{"label":"Revolver par","kind":"SUM","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_REVOLVER","op":"equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}]},{"label":"Delayed draw par","kind":"SUM","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_DELAYED_DRAW","op":"equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]},{"attribute":"IS_REVOLVER","op":"not_equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}]},{"label":"Unfunded commitments","kind":"SUM","attribute":"UNFUNDED_COMMITMENT_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_REVOLVER","op":"equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}]}],"scenario_mode":"strict","pre_trade":true,"denominator_terms":[{"label":"Collateral par","kind":"SUM","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}]}],"limit_term":{"kind":"MAX","attribute":"CLO_MAX_DELAYED_DRAW_REVOLVER_PCT","path":[{"relationship_code":"FUND_CLO_TRANSACTION","direction":"DOWN","recursive":false}]}}'),
    ('CLO_CONC_SINGLE_OBLIGOR', 'Par of each obligor group over collateral par. Obligors are grouped on OBLIGOR_GROUP_ID, so every issuer needs one (use the ultimate parent when there is no wider group).', 'POSITION', '[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}]', '[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false},{"relationship_code":"SECURITY_ISSUER","direction":"DOWN","recursive":false}]', 'OBLIGOR_GROUP_ID', 'FUNDED_PAR_AMOUNT', 'SUM', 'FUNDED_PAR_AMOUNT', 'SUM', 'ANCHOR_TOTAL', 'BASE', 'MAX', NULL::numeric, 2.0::numeric, 'PERCENTAGE', '{"scenario_mode":"strict","pre_trade":true,"limit_term":{"kind":"MAX","attribute":"CLO_MAX_SINGLE_OBLIGOR_PCT","path":[{"relationship_code":"FUND_CLO_TRANSACTION","direction":"DOWN","recursive":false}]}}'),
    ('CLO_CONC_INDUSTRY', 'Par of each Moody''s industry over collateral par. The largest industry may reach 12 percent and every other industry 10 percent. The rank limits are rule_thresholds rows and can be set per fund.', 'POSITION', '[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}]', '[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false},{"relationship_code":"SECURITY_ISSUER","direction":"DOWN","recursive":false}]', 'MOODYS_INDUSTRY_CODE', 'FUNDED_PAR_AMOUNT', 'SUM', 'FUNDED_PAR_AMOUNT', 'SUM', 'ANCHOR_TOTAL', 'BASE', 'MAX', NULL::numeric, 12.0::numeric, 'PERCENTAGE', '{"scenario_mode":"strict","pre_trade":true}'),
    ('CLO_ELIG_LOAN_TYPE', 'Count of holdings that are bridge loans, structured finance, synthetic securities or zero coupon obligations.', 'POSITION', '[]', '[]', NULL::varchar, 'FUNDED_PAR_AMOUNT', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MAX', NULL::numeric, 0.0::numeric, 'COUNT', '{"logic":"composite_ratio","numerator_terms":[{"label":"Prohibited Obligation Type","kind":"COUNT","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"CLO_LOAN_TYPE","op":"in","value":["BRIDGE","STRUCTURED_FINANCE","SYNTHETIC","ZERO_COUPON"],"path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}]}],"scenario_mode":"strict","pre_trade":true}'),
    ('CLO_ELIG_CONVERTIBLE', 'Count of holdings that can convert into equity or another currency.', 'POSITION', '[]', '[]', NULL::varchar, 'FUNDED_PAR_AMOUNT', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MAX', NULL::numeric, 0.0::numeric, 'COUNT', '{"logic":"composite_ratio","numerator_terms":[{"label":"Convertible Obligation","kind":"COUNT","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_CONVERTIBLE","op":"equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}]}],"scenario_mode":"strict","pre_trade":true}'),
    ('CLO_ELIG_STATED_MATURITY', 'Count of holdings that mature after the stated maturity of the notes.', 'POSITION', '[]', '[]', NULL::varchar, 'FUNDED_PAR_AMOUNT', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MAX', NULL::numeric, 0.0::numeric, 'COUNT', '{"logic":"composite_ratio","numerator_terms":[{"label":"Maturity Beyond Stated Maturity","kind":"COUNT","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"MATURITY_DATE","op":"gt","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}],"value_attribute":"CLO_STATED_MATURITY","value_path":[{"relationship_code":"FUND_CLO_TRANSACTION","direction":"DOWN","recursive":false}]}]}],"scenario_mode":"strict","pre_trade":true}'),
    ('CLO_ELIG_RATING_SP', 'Count of holdings rated below CCC- by S&P.', 'POSITION', '[]', '[]', NULL::varchar, 'FUNDED_PAR_AMOUNT', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MAX', NULL::numeric, 0.0::numeric, 'COUNT', '{"logic":"composite_ratio","numerator_terms":[{"label":"S&P Rating Floor","kind":"COUNT","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_DEFAULTED","op":"not_equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]},{"attribute":"CLO_SP_RATING_ORDINAL","op":"gt","value":"19","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}]}],"scenario_mode":"strict","pre_trade":true}'),
    ('CLO_ELIG_RATING_MOODYS', 'Count of holdings rated below Caa3 by Moody''s.', 'POSITION', '[]', '[]', NULL::varchar, 'FUNDED_PAR_AMOUNT', 'SUM', NULL::varchar, NULL::varchar, 'SAME_GROUP', 'BASE', 'MAX', NULL::numeric, 0.0::numeric, 'COUNT', '{"logic":"composite_ratio","numerator_terms":[{"label":"Moody''s Rating Floor","kind":"COUNT","attribute":"FUNDED_PAR_AMOUNT","path":[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}],"where":[{"attribute":"IS_DEFAULTED","op":"not_equals","value":"true","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]},{"attribute":"CLO_MOODYS_RATING_ORDINAL","op":"gt","value":"19","path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}]}],"scenario_mode":"strict","pre_trade":true}')
) AS v(code, descr, base_domain, base_path, group_path, group_attr, num_attr, num_agg, den_attr, den_agg,
       den_scope, den_source, direction, soft, hard, unit, meta)
  ON v.code = r.rule_code
ON CONFLICT (rule_id, version_number) DO UPDATE
SET description = EXCLUDED.description,
    base_domain_code = EXCLUDED.base_domain_code,
    base_rollup_path = EXCLUDED.base_rollup_path,
    group_by_path = EXCLUDED.group_by_path,
    group_by_attribute_code = EXCLUDED.group_by_attribute_code,
    numerator_attribute_code = EXCLUDED.numerator_attribute_code,
    numerator_aggregation = EXCLUDED.numerator_aggregation,
    denominator_attribute_code = EXCLUDED.denominator_attribute_code,
    denominator_aggregation = EXCLUDED.denominator_aggregation,
    denominator_scope = EXCLUDED.denominator_scope,
    denominator_source = EXCLUDED.denominator_source,
    limit_direction = EXCLUDED.limit_direction,
    soft_limit_value = EXCLUDED.soft_limit_value,
    hard_limit_value = EXCLUDED.hard_limit_value,
    result_unit = EXCLUDED.result_unit,
    metadata = EXCLUDED.metadata,
    rule_name = EXCLUDED.rule_name;

-- Every CLO rule runs only on a fund whose structure is CLO.
DELETE FROM compliance.rule_conditions c
USING compliance.rule_versions rv
JOIN compliance.rules r ON r.id = rv.rule_id
WHERE c.rule_version_id = rv.id
  AND r.rule_code LIKE 'CLO\_%'
  AND rv.version_number = 1;

INSERT INTO compliance.rule_conditions (
    rule_version_id, applies_to, condition_group, condition_order, attribute_code, operator, value, logic_operator, attribute_dimension
)
SELECT rv.id, 'ANCHOR', 1, 1, 'FUND_STRUCTURE', 'equals', 'CLO', 'AND', '{}'::jsonb
FROM compliance.rule_versions rv
JOIN compliance.rules r ON r.id = rv.rule_id AND rv.version_number = 1
WHERE r.rule_code LIKE 'CLO\_%';

-- Industry: the largest industry is held to the rule default (12 percent).
-- Every industry from rank 2 down is held to 10 percent. Set a fund row to
-- match a deal whose indenture says otherwise.
INSERT INTO compliance.rule_thresholds (rule_id, entity_id, group_value, rank_from, rank_to, hard_limit_value, applies, notes)
SELECT r.id, NULL, NULL, 2, NULL, 10, TRUE, 'Every industry below the largest'
FROM compliance.rules r
WHERE r.rule_code = 'CLO_CONC_INDUSTRY'
  AND NOT EXISTS (
      SELECT 1 FROM compliance.rule_thresholds t
      WHERE t.rule_id = r.id AND t.entity_id IS NULL AND t.group_value IS NULL
        AND t.rank_from = 2 AND t.valid_to = DATE '9999-12-31'
  );

NOTIFY pgrst, 'reload schema';
